          "analogy": "يشبه وسيط الأخطاء المركزي (Global Error Handler) قسم المفقودات والشكاوى في الفندق؛ يعالج أي مشكلة تحدث في أي غرفة ويقدم حلاً مهذباً ومنسقاً للنزيل.",
